  myDateComparator(mydate, cellValue) {
    var dateAsString = cellValue;
    if (dateAsString == null) return -1;
    //var dateParts = dateAsString.split('/');
    var cellDate = new Date(dateAsString);
    if (mydate.getTime() === cellDate.getTime()) {
      return 0;
    }
    if (cellDate < mydate) {
      return -1;
    }
    if (cellDate > mydate) {
      return 1;
    }
    return 0;
  }
